import os
import zipfile
import xml.etree.ElementTree as ET
import re

path = 'budget.xlsx'
print("exists:", os.path.exists(path), "size:", os.path.getsize(path) if os.path.exists(path) else None)

if not os.path.exists(path):
    raise SystemExit("file not found")

z = zipfile.ZipFile(path)
print("entries:", z.namelist())
print()

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

wb = ET.fromstring(z.read('xl/workbook.xml'))
for sheet in wb.find('m:sheets', NS):
    print("sheet:", sheet.attrib)

# Map sheet name -> rId
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels:
    rid_to_target[rel.attrib['Id']] = rel.attrib['Target']

# Shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sst.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{%s}t' % NS['m']))
        shared.append(text)

for sheet in wb.find('m:sheets', NS):
    name = sheet.attrib['name']
    rid = sheet.attrib['{%s}id' % NS['r']]
    target = rid_to_target[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target
    print(f"\n=== Sheet: {name} ({target}) ===")
    ws = ET.fromstring(z.read(target))
    for row in ws.iter('{%s}row' % NS['m']):
        for c in row.findall('{%s}c' % NS['m']):
            ref = c.attrib.get('r')
            t = c.attrib.get('t')
            v = c.find('{%s}v' % NS['m'])
            f = c.find('{%s}f' % NS['m'])
            if f is not None:
                val = f"FORMULA: {f.text}"
            elif v is not None:
                val = v.text
                if t == 's':
                    val = shared[int(val)]
            else:
                val = None
            if val is not None:
                print(f"{ref} ({t}): {val!r}")

