import re
import zipfile
import xml.etree.ElementTree as ET
from collections import defaultdict

NS_R = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

def local(tag):
    return tag.split('}')[-1]

z = zipfile.ZipFile('budget.xlsx')
names = z.namelist()

wb_root = ET.fromstring(z.read('xl/workbook.xml').decode('utf-8'))
sheets = [(sh.get('name'), sh.get(NS_R + 'id')) for sh in wb_root.iter() if local(sh.tag) == 'sheet']
print("SHEETS:", sheets)

rels = {}
rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels').decode('utf-8'))
for rel in rels_root.iter():
    if local(rel.tag) == 'Relationship':
        rels[rel.get('Id')] = rel.get('Target')
print("RELS:", rels)

shared = []
if 'xl/sharedStrings.xml' in names:
    ss_root = ET.fromstring(z.read('xl/sharedStrings.xml').decode('utf-8'))
    for si in ss_root.iter():
        if local(si.tag) == 'si':
            shared.append(''.join(t.text or '' for t in si.iter() if local(t.tag) == 't'))
print("SHARED COUNT:", len(shared))

for name, rid in sheets:
    target = rels.get(rid, '')
    if target.startswith('/'):
        target = target[1:]
    elif not target.startswith('xl/'):
        target = 'xl/' + target
    print(f"--- sheet '{name}' target={target} ---")
    sheet_root = ET.fromstring(z.read(target).decode('utf-8'))
    dim = next((e.get('ref') for e in sheet_root.iter() if local(e.tag) == 'dimension'), None)
    print("DIMENSION:", dim)
    sums = defaultdict(float)
    for c in sheet_root.iter():
        if local(c.tag) != 'c':
            continue
        ref = c.get('r')
        t = c.get('t')
        v = None
        for child in c:
            if local(child.tag) == 'v':
                v = child.text
            elif local(child.tag) == 'is':
                v = ''.join(x.text or '' for x in child.iter() if local(x.tag) == 't')
        if v is None:
            continue
        if t == 's':
            val = shared[int(v)]
        elif t == 'b':
            val = v == '1'
        elif t in ('str', 'inlineStr'):
            val = v
        else:
            try:
                val = float(v)
                if val.is_integer():
                    val = int(val)
            except ValueError:
                val = v
        print(ref, repr(val))
        if isinstance(val, (int, float)):
            col = re.match(r'[A-Z]+', ref).group(0)
            sums[col] += val
    for col in sorted(sums):
        print(f"SUM[{col}] = {sums[col]}")

